def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Color the inner cells of each solid 1-rectangle, using the nearest
    # marker color. Rectangular patches are separated by background gaps.
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    a, b = y+dy, x+dx
                    if 0 <= a < h and 0 <= b < w and grid[a][b] == 1 and (a,b) not in seen:
                        seen.add((a,b))
                        stack.append((a,b))
            top = min(y for y,x in cells)
            bot = max(y for y,x in cells)
            left = min(x for y,x in cells)
            right = max(x for y,x in cells)
            members = set(cells)

            # Only fill genuinely rectangular components.
            if len(members) != (bot-top+1)*(right-left+1):
                continue
            markers = [(abs(y-(top+bot)//2)+abs(x-(left+right)//2), grid[y][x])
                       for y in range(h) for x in range(w)
                       if grid[y][x] not in (0,1)]
            if not markers:
                continue
            color = min(markers)[1]
            for y in range(top+1, bot):
                for x in range(left+1, right):
                    out[y][x] = color

    # Retain the original marker cells.
    for r in range(h):
        for c in range(w):
            if grid[r][c] not in (0, 1):
                out[r][c] = grid[r][c]
    return out
